const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, LevelFormat } = require('docx');
const fs = require('fs');

const { stagePath } = require('./stage');
// ---------- helpers ----------
const P = (text, opts = {}) => new Paragraph({
  spacing: { after: 200 },
  ...opts,
  children: [new TextRun({ text, ...(opts.run || {}) })]
});

// paragraph from segments: [{t: "text", b: bool, i: bool}]
const PS = (segs, opts = {}) => new Paragraph({
  spacing: { after: 200 },
  ...opts,
  children: segs.map(s => new TextRun({ text: s.t, bold: !!s.b, italics: !!s.i, color: s.c }))
});

const DM = (t) => ({ t, b: true, c: "5B1F1F" });   // DM-only marker: bold book-red
const H1 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_1, keepNext: true, children: [new TextRun(t)] });
const H2 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_2, keepNext: true, children: [new TextRun(t)] });
const H3 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_3, keepNext: true, children: [new TextRun(t)] });

const BULLET = (segs) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 120 },
  children: segs.map(s => new TextRun({ text: s.t, bold: !!s.b, italics: !!s.i, color: s.c }))
});

const NUMBERED = (segs, instance = 0) => new Paragraph({
  numbering: { reference: "numbers", level: 0, instance },
  spacing: { after: 120 },
  children: segs.map(s => new TextRun({ text: s.t, bold: !!s.b, italics: !!s.i, color: s.c }))
});
// An enumerated list numbers itself. Writing the number into the text instead
// leaves the glyph in place beside it, which is what "1." next to a bullet is.
// Every list sharing an instance numbers straight through, so a second list in
// the same document needs a fresh one.
const NUM = (lead, rest, instance = 0) => NUMBERED(
  lead ? [{ t: lead + " ", b: true }, { t: rest }] : [{ t: rest }], instance);
const B = (lead, rest) => PS([{ t: lead + " ", b: true }, { t: rest }]);
const BUL = (lead, rest) => BULLET(lead ? [{ t: lead + " ", b: true }, { t: rest }] : [{ t: rest }]);
const { Table, TableRow, TableCell, WidthType, ShadingType, TableLayoutType } = require('docx');
// Column widths in twips. docx-js emits a dummy equal-width <w:tblGrid> when
// columnWidths is absent, and LibreOffice honours that grid over the per-cell
// percentages -- every table renders with evenly split columns. Passing the
// grid explicitly, with a fixed layout, is what makes the widths array mean
// anything. Proportions are what matter; tblW=100% governs the total.
const CW = (w) => { const t = w.reduce((a, b) => a + b, 0); return w.map((x) => Math.round(9026 * x / t)); };

const cell = (text, opts = {}) => new TableCell({ width: { size: opts.w || 20, type: WidthType.PERCENTAGE }, shading: opts.head ? { type: ShadingType.CLEAR, fill: "E4DCCB" } : undefined, margins: { top: 50, bottom: 50, left: 45, right: 45 }, children: [new Paragraph({ spacing: { after: 0 }, alignment: AlignmentType.LEFT, indent: { firstLine: 0 }, children: [new TextRun({ text, bold: !!opts.head, size: 18 })] })] });
// Body rows may split across a column break. cantSplit here would stop the whole table
// from flowing into the next column, and LibreOffice answers that by dropping the rows
// that no longer fit -- silently, with the build reporting clean. The header row keeps
// cantSplit and repeats above the continuation instead.
const row = (cells) => new TableRow({ children: cells });
// The header row repeats when a long table spans a column or page break.
const headerRow = (cells) => new TableRow({ children: cells, cantSplit: true, tableHeader: true });
const table = (headers, widths, rows) => new Table({ width: { size: 100, type: WidthType.PERCENTAGE }, columnWidths: CW(widths), layout: TableLayoutType.FIXED, rows: [ headerRow(headers.map((h, i) => cell(h, { head: true, w: widths[i] }))), ...rows.map(r => row(r.map((v, i) => cell(v, { w: widths[i] })))) ] });
const mod = (v) => { const m = Math.floor((v - 10) / 2); return (m >= 0 ? "+" : "\u2212") + Math.abs(m); };
const abCell = (text, bold) => new TableCell({ width: { size: 16.6, type: WidthType.PERCENTAGE }, shading: bold ? { type: ShadingType.CLEAR, fill: "E4DCCB" } : undefined, children: [new Paragraph({ keepNext: !!bold, alignment: AlignmentType.CENTER, spacing: { after: 40, before: 40 }, children: [new TextRun({ text, bold: !!bold, size: 20 })] })] });
const SB = (d) => { const out = []; out.push(new Paragraph({ keepNext: true, spacing: { before: 240, after: 40 }, children: [new TextRun({ text: d.name, bold: true, size: 26, color: "5B1F1F" })] })); out.push(PS([{ t: d.meta, i: true }], { keepNext: true, spacing: { after: 120 } })); out.push(B("Armor Class:", d.ac)); out.push(B("Hit Points:", d.hp)); out.push(B("Speed:", d.speed)); out.push(new Table({ width: { size: 100, type: WidthType.PERCENTAGE }, columnWidths: CW([1, 1, 1, 1, 1, 1]), layout: TableLayoutType.FIXED, rows: [ new TableRow({ cantSplit: true, children: ["STR","DEX","CON","INT","WIS","CHA"].map(h => abCell(h, true)) }), new TableRow({ cantSplit: true, children: [d.str,d.dex,d.con,d.int,d.wis,d.cha].map(v => abCell(v + " (" + mod(v) + ")")) }) ] })); out.push(P("", { spacing: { after: 60 } })); if (d.saves) out.push(B("Saving Throws:", d.saves)); if (d.skills) out.push(B("Skills:", d.skills)); if (d.resist) out.push(B("Damage Resistances:", d.resist)); if (d.immune) out.push(B("Damage Immunities:", d.immune)); if (d.condimmune) out.push(B("Condition Immunities:", d.condimmune)); if (d.senses) out.push(B("Senses:", d.senses)); if (d.langs) out.push(B("Languages:", d.langs)); out.push(B("Challenge:", d.cr)); (d.traits||[]).forEach(t => out.push(PS([{ t: t.n + ". ", b: true, i: true }, { t: t.t }]))); if (d.actions && d.actions.length) { out.push(PS([{ t: "ACTIONS", b: true }], { keepNext: true, spacing: { before: 80, after: 80 } })); d.actions.forEach(a => out.push(PS([{ t: a.n + ". ", b: true, i: true }, { t: a.t }]))); } if (d.reactions && d.reactions.length) { out.push(PS([{ t: "REACTIONS", b: true }], { keepNext: true, spacing: { before: 80, after: 80 } })); d.reactions.forEach(a => out.push(PS([{ t: a.n + ". ", b: true, i: true }, { t: a.t }]))); } return out; };


// ---------- content ----------
const children = [];

// Title block
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 300 },
  children: [new TextRun({ text: "The Qilvayas Symphony", bold: true, size: 44 })]
}));
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 120 },
  children: [new TextRun({ text: "A Dungeons & Dragons 5th Edition Campaign Setting", italics: true, size: 26 })]
}));
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 400 },
  children: [new TextRun({ text: "~", size: 24 })]
}));
children.push(PS([
  { t: "\u201CI gaze upon the night sky admiring the stars strewn across Heaven\u2019s field. Each one a testament of power, its light piercing through the void to shine upon us. And now to our dawn light I summon you. Lord, have mercy upon us sinful children of Zhuvedus. Give us your light, Lord\u2026and give me my destiny. I am Qilvayas, Emperor of the Zhuvedians. We are the Kin of Great Timberwolf.\u201D", i: true }
]));
children.push(PS([{ t: "\u2014Prayer of Qilvayas on the eve of his coronation", i: true }], { spacing: { after: 400 } }));

// Campaign Overview
children.push(H1("Campaign Overview"));
children.push(P("The Qilvayas Symphony is a campaign of imperial ambition, prophetic visions, and moral complexity set against the backdrop of a crumbling empire. Drawing inspiration from Byzantine history \u2014 particularly the struggles of emperors like Justinian who sought to restore former Roman glory \u2014 this campaign explores themes of legacy, power, the cost of idealism, and the tension between the dream of unity and the reality of a fractured world."));
children.push(P("The player characters are final-year students at the prestigious Imperial Academy of the Lupine Throne, completing their field exercises and planning their futures as independent adventurers. When they receive a shared prophetic vision of the capital city in flames and a monstrous shadow in storm clouds above, they are drawn into events that will test their abilities, challenge their loyalties, and potentially determine the fate of the empire itself."));

// Historical Background
children.push(H1("Historical Background"));
children.push(H2("The Height of Empire"));
children.push(P("At its zenith, the Empire of Zhuvedus spanned nearly an entire continent. United under the Lupine Throne and guided by the principles of the Lupine Matron, the empire represented civilization, law, and order. The Golden Tablets \u2014 sacred legal codes established by the empire\u2019s forefathers \u2014 formed the foundation of Zhuvedian governance and culture. Trade flourished along imperial roads, justice was administered by trained magistrates, and the imperial legions defended the borders against external threats."));
children.push(P("The imperial capital, seat of the Lupine Throne, was the beating heart of this civilization \u2014 a center of learning, culture, and power that drew the ambitious and talented from across the realm."));
children.push(H2("Two Centuries of Decline"));
children.push(P("The empire\u2019s decline was not sudden but gradual \u2014 a slow erosion over two hundred years. Internal strife between noble houses weakened central authority. Corruption spread through the bureaucracy as distant provinces found ways to avoid imperial taxation and oversight. Military expeditions to reclaim lost territories or suppress rebellions failed, draining the treasury and damaging the legions\u2019 reputation. External powers, sensing weakness, pressed against the borders and even seized imperial territory."));
children.push(P("Most devastatingly, the empire fractured. What had been provinces became semi-independent \u201Cnations,\u201D each ruled by ambitious warlords, merchant councils, or noble houses who once swore fealty to the throne but now pursued their own interests. Some maintained the fiction of imperial loyalty while ignoring imperial law. Others openly declared independence. Still others warred among themselves, creating a patchwork of competing powers where once there had been unity."));
children.push(P("The imperial capital remained, and the Lupine Throne was still occupied, but the reach of imperial authority had shrunk dramatically. The empire existed more in memory and aspiration than in reality."));

// Current State
children.push(H1("The Empire of Zhuvedus: Current State"));
children.push(H2("Political Landscape"));
children.push(P("The empire today is a shadow of its former self, yet it persists. The imperial capital and its surrounding territories remain under direct imperial control, and several regions still recognize the Lupine Throne\u2019s authority \u2014 some genuinely, others opportunistically. The fractured \u201Cnations\u201D present a complex political landscape:"));
children.push(B("Border Lords and Regional Powers:", "Former provincial governors, military commanders, and noble houses now rule territories as de facto independent states. Their relationship with the throne varies \u2014 some maintain nominal loyalty while ignoring imperial edicts, others have declared independence outright, and a few actively work against reunification to protect their autonomy."));
children.push(B("Merchant Republics:", "Wealthy trading cities that broke away to avoid imperial taxation, now governed by councils of merchants and guild masters. They prefer the current disorder, which allows them to play different powers against each other for commercial advantage."));
children.push(B("Warlord Territories:", "Regions held by military strongmen who rose to power during the empire\u2019s collapse. Some style themselves as protectors of order, others are little better than bandits with armies."));
children.push(B("Imperial Loyalists:", "Territories that still genuinely support the throne, either out of tradition, religious conviction in the Lupine Matron\u2019s divine mandate, or pragmatic belief that a restored empire offers better stability than the current chaos."));
children.push(P("The borders are fluid and contested. Alliances shift, minor wars flare up and sputter out, and ambitious lords constantly scheme for advantage. Into this volatile situation steps Emperor Qilvayas with his vision of restoration."));

children.push(H2("Atlas of the Fractured Empire"));
children.push(P("The territories below are the ones most likely to matter in the campaign\u2019s first arcs \u2014 not an exhaustive map. Distances by imperial road: the Ostmark is four days east of Aenodira, the Brekelands roughly two weeks west, Tarnovar three weeks into the western highlands, Velmareth ten days downriver."));
children.push(B("The Crownlands:", "The imperial core \u2014 Aenodira, its river valley, and the districts within a week\u2019s march \u2014 under direct rule and the only place imperial law functions at full strength. Prosperous by current standards, anxious by any other measure: everyone in the Crownlands lives inside the restoration project, whether they believe in it or not. Capital culture runs on the race-days of the Long Course, where the city\u2019s two great factions \u2014 the Golds and the Greys, named for the stone of the walls they claim \u2014 turn sport into politics and politics into sport (see Plot Hooks: The Grey-Gold Rising)."));
children.push(B("The Ostmark:", "The eastern march, held by thin legion garrisons and thick tradition. Loyalist by conviction in the towns (Dravenna among them) and by inertia in the countryside. The Third Provincial Legion scandal \u2014 Colonel Aurel Dessen, who sold his garrison\u2019s grain and blamed the men who fled \u2014 is exactly the kind of rot that decides whether places like this stay loyal. Magistrate Cassivar Ondrei\u2019s complaint about it is somewhere in a capital inbox. The march\u2019s pride, and the throne\u2019s quiet anxiety, is Marshal Gavric Dane (see The Powers of the Fractured Empire), the young commander who brought a lost wolf-standard home."));
children.push(B("The Suthmark:", "The southern breadbasket, genuinely loyalist and deeply devout \u2014 the Matron\u2019s faith runs older and plainer here than in the capital: harvest processions, field-shrines, saints\u2019 days kept by planting calendars. Governed by the ducal house of Vasq \u2014 the young Duke Aldous in law, and his mother the Dowager Duchess Emerenn in fact (see The Powers of the Fractured Empire), Velmareth-born and iron beneath the mourning silk, whose loyalty is sincere and whose patience is not unlimited. The south still carries two scars it does not discuss with outsiders: the Vintage Night, six years past, and the hill country around Castle Greywell, where servant girls have a way of not coming home."));
children.push(B("Principality of Tarnovar:", "A highland nation in the far west, openly independent for a century and pointedly uninterested in reunification. Tarnovari culture is built on the given word: oaths are sworn on standing stones rather than gods, oath-breaking is the one unforgivable crime, and their oldest ballads mourn a betrayed lord called Vosthren, whose story no imperial scholar has ever bothered to trace. Their proverb for treating with the throne: \u201CNever again the wolf\u2019s word.\u201D Ruled by the aging, canny Voivode Ysavet Morn \u2014 whose word is absolute everywhere except the Eastmarch, where her kinsman Ban Dregan Morn keeps the border with the Brekelands by methods she has never sanctioned and never stopped (see The Powers of the Fractured Empire)."));
children.push(PS([DM("DM Only: "), { t: "Tarnovar is what became of Threnvos\u2019s people. \u201CVosthren\u201D is Threnvos, syllable-inverted by twenty centuries of oral drift \u2014 a name the Church never thought to suppress because it never recognized it. The Tarnovari do not know their own true origin; their stone-oath customs and their instinctive distrust of imperial promises are cultural scar tissue from a wound no living person can name. This is a mid-campaign revelation of enormous weight: proof of the buried founding account exists in living culture, not just old stones \u2014 and depending on how it surfaces, Tarnovar becomes the empire\u2019s natural ally against the shadow or the rightful claimant its founding wronged. Handle with care; do not spend it early." }]));
children.push(B("Free City of Velmareth and the Delta Compact:", "The great merchant republic of the river delta and the league of trading towns in its orbit. Rich, ostentatiously neutral, and quietly committed to the fractured status quo \u2014 disorder is margin. The Merchant Republic delegations at Aenodira\u2019s Exchange answer, eventually, to Velmareth\u2019s Harborlords \u2014 among whose great banking houses the Meldane name still opens every door, a fact of continuing relevance to the Suthmark (see Duchess Emerenn Vasq)."));
children.push(B("The Brekelands:", "The broken middle-west: a patchwork of warlord holdings where imperial administration simply stopped. The local trouble is the Granary War \u2014 warlords Bettra Skarn and Ilmarch Voss burning each other\u2019s villages over a dispute neither remembers clearly \u2014 which produced the Halvenne refugees and three other burned villages this season. But the Granary War is a squabble between men who cannot see the weather coming: from the west, Duke Garvin Norr absorbs one warlord holding after another into Normere\u2019s Reckoning Book, and along the eastern hills runs Ban Dregan\u2019s Fence, which no Brekeland company raids past twice."));
children.push(B("The See of Orlath:", "A breakaway patriarchate in the north claiming the purer doctrine of the Matron \u2014 founded nearly sixty years ago by Saint-Regent Olvesa the Reconciled (see The Powers of the Fractured Empire), a woman whose road to sanctity ran through one of the most terrible vengeances in northern memory. Orlath recognizes neither the Matriarchate\u2019s authority nor the Office of Omens\u2019 monopoly on the divine will, and refugees of conscience \u2014 clergy who fell out with the Sanctum \u2014 drift there still. What the capital has not yet understood: Orlath is no longer merely a schism. It is preparing a coronation \u2014 and when the crown is set, Olvesa\u2019s sixty-year regency ends, its whole purpose discharged."));
children.push(B("Kingdom of Ardven:", "The young power of the far north, beyond Orlath: a dozen quarrelsome kingdoms and clan-lands hammered into one crown over fifteen years by King Karvel (see The Powers of the Fractured Empire). Ardven is expansionist, literate, and increasingly confident \u2014 Karvel plants monastery schools the way other kings plant fortresses, and his court hosts scholars the empire\u2019s academies lost to poverty or politics. His consolidation of the northern coasts has had one consequence the empire feels directly: the ship-clans of the Skellvard, driven from fjords they held for generations, now raid southward with nowhere to return to."));
children.push(B("The Skellvard:", "Sea-lords raiding the imperial coast in growing strength \u2014 but raiders is only half the truth. The Skell ship-clans are a displaced people, pushed from their northern harbors by Ardven\u2019s expansion, led by Sea-King Aldrec the Landless (see The Powers of the Fractured Empire), who once served the empire and was cheated for it. Skell culture keeps tally-sticks of every debt owed and every promise broken; their raids are recorded, clan by clan, as collections. Their kings are buried beneath rivers, in secret, so that no enemy may ever stand on a Skell king\u2019s grave \u2014 a people whose deepest fear is having nowhere to be buried at all."));
children.push(B("The Duchy of Normere:", "The iron surprise of the west coast: a once-minor duchy forged into the most efficient state in the fractured empire by Duke Garvin Norr, the Bastard of Normere (see The Powers of the Fractured Empire). Normere\u2019s instruments are famous and feared in equal measure \u2014 the Reckoning Book, a census of every hide of land and head of livestock the Duke rules; the personal oath every landholder swears to Norr himself, bypassing all intermediate lords; and the memory of the Harrowing of the Weld, four years past, when a rebellious district learned what the Duke\u2019s patience costs when it runs out. Norr is not resisting reunification. He is conducting his own."));

children.push(H3("Imperial and Border Jurisdiction, at a Glance"));
children.push(P("Imperial law does not mean the same thing twice past the Crownlands\u2019 border. The table below is a single page for a question the Atlas otherwise answers one region at a time: where the Laws actually run, and who actually enforces whatever does."));
children.push(table(["Region","Status","Who Actually Enforces"],[23, 32, 45],[
  ["The Crownlands","Direct Rule \u2014 imperial law at full strength","The Palatine Guard; imperial magistrates"],
  ["The Ostmark","Loyalist Provincial \u2014 nominal, unevenly enforced","Thin legion garrisons; Magistrate Ondrei\u2019s model"],
  ["The Suthmark","Loyalist Provincial \u2014 genuinely loyal, governed through the ducal house","Duke Aldous in law; the Dowager Duchess\u2019s household authority in fact, alongside the Church"],
  ["Principality of Tarnovar","Sovereign Treaty-Nation \u2014 imperial law does not apply","Oath-custom; the Voivode; Ban Dregan\u2019s Fence (unsanctioned even internally)"],
  ["Velmareth and the Delta Compact","Sovereign Treaty-Nation \u2014 own mercantile law; the Marked hold actual legal standing here, uniquely","The Harborlords; the Compact\u2019s own courts"],
  ["The Brekelands","Contested / Warlord \u2014 imperial statute on the books, unenforced","Individual warlords; no appeal exists"],
  ["The See of Orlath","Parallel Legal-Religious Authority \u2014 rejects the Matriarchate and the Office of Omens alike","Olvesa\u2019s See; its own rival Sanction"],
  ["Kingdom of Ardven","Sovereign Treaty-Nation \u2014 an independent, literate, expansionist crown","King Karvel\u2019s own developing law"],
  ["The Skellvard","Non-Territorial Customary Law \u2014 no fixed land, no codified statute","Clan lawspeakers; tally-sticks record debts and broken promises"],
  ["The Duchy of Normere","De Facto Replacement \u2014 imperial law formally claimed, functionally superseded","Duke Norr\u2019s personal-oath system and the Reckoning Book"]
]));
children.push(P("One exception is worth flagging rather than generalizing: Velmareth\u2019s grant of legal standing to the Marked has no imperial equivalent, and whether it ever becomes one is a live question the Zhuvedian Laws do not yet answer."));

// ==================== PART V: THE ATLAS, FLESHED ====================
children.push(H2("The Regions in Depth"));
children.push(P("Per the approved full-fantasy dial: monsters are common, dragons are active, and the wild is genuinely wild. Creature lists name SRD monsters except where a name is followed by a bracketed dagger \u2014 (\u2020) \u2014 which marks a Monster Manual creature outside the SRD, to be looked up rather than pulled from the open data. Each region: the land, who lives there, what hunts there, and named settlements."));

children.push(H3("The Crownlands"));
children.push(PS([{ t: "The land: the Ostrun\u2019s broad valley \u2014 terraced grain, cypress windbreaks, poplar-lined imperial roads, and the capital\u2019s three walls rising out of river haze. Old, worked, beautiful, tired. Peoples: Zhuvedian humans, Coppergate halflings, the masons\u2019 dwarves, faded high-elf houses, the Craft\u2019s gnomes \u2014 and the dynasty, alone in its blood. Creatures: mostly human dangers, plus the city\u2019s famous exceptions \u2014 wererats (\u2020) in Rivergate\u2019s deep cellars (the Watch denies it; the Inkhands charge a surcharge for jobs below the waterline), the Garrison\u2019s last three griffons (the wing was forty strong at the height of empire; the riders\u2019 hall keeps every empty saddle oiled), and the wolves of Aenodira \u2014 sacred, protected, and " }, DM("(DM only) "), { t: "leaving the Old Forum district family by family for three years. Settlements: Aenodira (canon); Varn\u2019s Crossing (canon \u2014 the toll bridge); Lupenna, a pilgrim town at the Matron\u2019s first roadside shrine, all candle-stalls and wolf-icons; Whitequay, a river town that ships the valley\u2019s grain and remembers when it shipped ten times more." }]));

children.push(H3("The Ostmark"));
children.push(P("The land: big-sky plains breaking into wooded hills eastward, watch-forts on the heights (Redwatch was one of a chain \u2014 most now stand empty), and the trade road running through it all like a nerve. Peoples: Ostfolk humans and the marches\u2019 respected half-orc veteran families; a legion culture even where the legions are thin. Creatures: wolf packs (read for omens), worgs where the old auxiliary kennels went feral, ogres in the hill country, ankhegs in the grain flats, griffons nesting the crags (the legions once took eggs under license; nobody has dared in a generation), and wights (\u2020) and worse in the failed watch-forts \u2014 dead garrisons make bad neighbors, and the shadow\u2019s stirring is making them restless. Settlements: Dravenna (canon); Kolvess, the Third Legion\u2019s garrison town, where Colonel Dessen\u2019s name is said carefully; Serren\u2019s Mill, a crossroads village famous for poppy-milk and for minding its own business."));

children.push(H3("The Suthmark"));
children.push(P("The land: golden grain to the horizon, vineyard terraces, chalk downs, and \u2014 eastward \u2014 the grey hollows of the Greywell hills, where the light arrives late and leaves early. Peoples: devout Suthfolk humans, halfling harvest-clans, hill dwarves in the east (whose families have learned the valley\u2019s law does not climb). Creatures: ankhegs (the grain country\u2019s classic plague \u2014 harvest-festival effigies are shaped like them), giant boars, blights in the old orchards, a confirmed green hag somewhere in the Greywell watershed (the valley folk leave her be, on the reasonable grounds that she is not the worst thing in those hills), and harvest-fey of the Old Observance \u2014 sprites and a dryad grove the Church politely does not discuss. Settlements: Caldessa, the ducal seat \u2014 wine, mourning-silk, and the Garland\u2019s quiet ears in every kitchen; Ambervale, a harvest town that hosts the south\u2019s great festival (and was one of the three towns of the Vintage Night \u2014 the festival has a new route now, avoiding certain streets); Greywell-under-Hill, the village at the castle\u2019s feet, where the wages are good."));

children.push(H3("Principality of Tarnovar"));
children.push(P("The land: the empire\u2019s deep wilderness \u2014 montane mist-forest rising to bare stone, the standing-stone rings on the bald summits, valleys where noon looks like evening. The Old Wood at its heart is the largest unbroken forest in the fractured world. Peoples: Tarnovari humans and the Stonesworn dwarves (a third of the nation, fully Tarnovari), wood-elf communities deep in the Old Wood keeping the eldest ballads \u2014 including, unknowing, the truest ones. Creatures: owlbears, ettercaps and their webs in the pine deeps, green hags at the fey margins, elk and giant elk, winter wolves on the high passes \u2014 and the Old Wood\u2019s fey-touched heart, where the Hollow Hills stand and travelers\u2019 time runs strange (a soft Feywild adjacency, never named onstage). Settlements: Kamenhold, the Voivode\u2019s seat, built dry-stone into a mountainside \u2014 the oath-stones of every Tarnovari family stand in its high field; Fencegate, Ban Dregan\u2019s border fort on the Eastmarch, beyond which the stakes begin; Verath, an Old Wood village of singers \u2014 Ilinca\u2019s home \u2014 where the Lament cycle is kept whole."));

children.push(H3("Free City of Velmareth and the Delta Compact"));
children.push(P("The land: the Ostrun\u2019s delta \u2014 reed-seas, tidal channels, and the lagoon city itself: Velmareth on its ten thousand pilings, all bridges, salt-stained marble, and money. Peoples: everyone \u2014 the true cosmopolis; Velmarene humans and half-elves, halfling middle guilds, Marked (tiefling) quarters with actual legal standing, Sarkanni mercenary lodges, and anything the tide brings. Creatures: giant crocodiles in the reed-sea, merrow in the outer channels (the Compact pays a \u2018channel-toll\u2019 it does not describe in its ledgers), water elementals bound as harbor-engines by chartered thaumaturges, swarms of everything \u2014 and, in the drowned quarter\u2019s oldest cellars, things the Harborlords\u2019 dredge-teams are paid triple to not discuss. Settlements: Velmareth itself; Saltmark, the Compact\u2019s toll-town at the delta mouth; Reedhaven, a stilt-village of pilots and smugglers who are often the same families."));

children.push(H3("The Brekelands"));
children.push(PS([{ t: "The land: broken hill country \u2014 hedgerows gone wild between burned granges, mill-streams turning no wheels, roads that fork around the ruins of villages that were the reason for the roads. Peoples: Brekelander humans \u2014 tough, displaced, warlord-taxed \u2014 and everyone\u2019s deserters. Creatures: the war\u2019s harvest \u2014 gnolls (famine-born packs following the burnings; the old folk say gnolls are what hunger prays to), ghouls and ghasts at the burn sites (betrayal-fed dead: Halvenne\u2019s ashes are already whispered about), wyverns in the high crags taking cattle and the occasional tax-collector, and manticores that learned to follow armies. (" }, DM("DM only: "), { t: "the ghoul-density at parley-breach sites is not natural, and it is rising. The Brekelands are the shadow\u2019s best-fed province outside the capital.) Settlements: Skarnhold and Vosskeep, the rival warlord seats, each convinced it is the reasonable one; Millbreak, a neutral market town that survives by being useful to everyone and loyal to no one \u2014 the Brekelands in one village." }]));

children.push(H3("The See of Orlath"));
children.push(P("The land: taiga edge and fell-country \u2014 pilgrim roads switchbacking to the mountain city, prayer-cairns at every false summit, and the Reconciliation Shrine above the treeline where Olvesa spent her year. Peoples: Orlathine humans \u2014 penitent, rigorous, warmer than their liturgy \u2014 and clergy refugees from every Sanctum quarrel of the last forty years. Creatures: winter wolves (Orlath reads them as the Matron\u2019s northern honor guard and feeds them at the pilgrim stations \u2014 a practice the Sanctum calls heresy and the wolves call dinner), polar bears and saber-cats on the high fells, trolls in the ravines, banshees (\u2020) on the Drevic moors \u2014 the old clan-lands never quite finished grieving \u2014 and ice mephits in the shrine-heights. Settlements: Orlath, the see-city, carved switchback galleries and the Second Treasury of Relics; Penitent\u2019s Stair, the last town before the Shrine, economy of candles, crutches, and confessions; Drevholm, the quiet town on the old clan-lands, where nobody sings."));

children.push(H3("Kingdom of Ardven"));
children.push(P("The land: fjords and pine-clad steeps, longhouse towns turning to slate-roofed monastery burghs as Karvel\u2019s new order spreads \u2014 the north mid-transformation, timber to stone, saga to script. Peoples: Ardvenner humans, wood-elf enclaves in the wilds, dwarven quarry-towns under royal charter. Creatures: the Fjell Whites \u2014 a brood of young white dragons in the high ranges that Karvel\u2019s rangers cull like wolves-of-state (an adult matriarch is unconfirmed; the rangers\u2019 silence on the question is its own answer); frost giants in the far fells, with whom Karvel maintains a tribute-truce he finds humiliating and keeps anyway; trolls, winter wolves, mammoths on the tundra edge; and giant eagles that the northern kings once flew \u2014 Karvel is trying to revive the mews, because of course he is. Settlements: Karvholm, the new capital \u2014 half longhouse, half cathedral, all ambition; Lettervik, the monastery town where forty schools\u2019 worth of scribes are teaching the north to write; Fjellgard, the ranger town under the dragon-fells, quietly the toughest place in the kingdom."));

children.push(H3("The Skellvard"));
children.push(P("The land: not land \u2014 the cold sea itself, island anchorages, whale-roads, and the drowned fjords the clans lost to Ardven\u2019s expansion. The Skell live aboard; the fleets are the nation. Peoples: Skell humans \u2014 salt-cured, tally-keeping, courteous in the way of people who remember everything. Creatures: hunter sharks and killer whales (clan-omens), merrow war-bands (old enemies, old treaties), harpies on the guano stacks, a plesiosaurus breed the clans call sea-elk and herd \u2014 herd \u2014 and, beneath the Weeping Strait, the Saltmaw (see Part VI). Settlements (such as they are): the Gathering Roads, the great fleet-moot in the lee of the Broken Isles, a city that exists two months a year; Wrecksalt Isle, the beaching-ground, shipwright\u2019s yard, and the closest thing the landless have to holy ground \u2014 no king is buried there; that is the point of it."));

children.push(H3("The Duchy of Normere"));
children.push(PS([{ t: "The land: rain-lashed headlands, drained polder-fields behind the Duke\u2019s dikes (the Reckoning Book records every sluice), slate towns of ruthless neatness, and castles placed like arguments. Peoples: Normerine humans \u2014 administered, prosperous, watchful \u2014 and hired dwarven stonewrights on chartered terms. Creatures: the coast\u2019s merrow and sahuagin raiders (Norr\u2019s shore-levies drill against them monthly; attendance is recorded), wights in the pre-ducal barrows (Norr\u2019s surveyors map them and build around, to the letter of an old accommodation nobody writes down) \u2014 and the Weld. (" }, DM("DM only: "), { t: "the Harrowing left revenants (\u2020) \u2014 vengeance-oath dead \u2014 walking the burned district. Norr knows. The Weld is the one entry in the Reckoning Book with no numbers in it, and the one place his personal oath-web has a hole in it. The shadow has noticed the hole.) Settlements: Norr\u2019s Watch, the ducal seat \u2014 the Reckoning Book\u2019s hall is open to any sworn subject, which is either transparency or the largest threat ever bound in vellum; Slateharrow, the naval port; the Weld, which is on the maps and off the itineraries." }]));


// ==================== PART VI: DRAGONS ====================
children.push(H1("Dragons of the Fractured Age"));
children.push(H3("Vessarkath the Patient \u2014 the Silvasse Weald"));
children.push(P("Ancient green dragon (SRD), and the true author of the Silvasse Disaster: sixty years ago, three legions marched into her wood \u2014 hers for eight centuries \u2014 and she did what patience does. She has slept on their eagles ever since, which reframes canon without contradicting it: Marshal Dane\u2019s recovery of the Ninth\u2019s standard from \u2018the Brekelands warlords\u2019 stands \u2014 the warlords had it because Vessarkath let one standard leave her hoard, through channels, some fifty-seven years after taking it. Why she permitted it is DM-only, and now settled canon: she moved in the season the shadow beneath Aenodira stirred (see The Acceleration). A creature that has kept that wood for eight centuries feels a wound that old reopen the way lesser things feel a change in the weather, and she does not sleep through it. Marshal Dane\u2019s legend is, without his knowing, a shadow-artifact \u2014 the standard came home because something under the capital woke \u2014 and the one creature in the world who could ever tell him so is the dragon that felt it move. She does not raid; she does not treat; she receives. The Brekelands warlords\u2019 unspoken western border is not Norr. It was never Norr."));
children.push(H3("The Saltmaw \u2014 the Weeping Strait"));
children.push(P("Dragon turtle (SRD), old beyond clan-memory, dwelling beneath the strait where the empire spent three thousand Skell lives. The clans propitiate it with the salt-tithe \u2014 cargo given to the water at the strait\u2019s mouth \u2014 and its interventions are weather to them: unpredictable, unappealable, occasionally merciful. DM-option, flagged within a flag: what the imperial admiral\u2019s squadrons actually fled at the Weeping Strait \u2014 the battle canon leaves unspecified \u2014 may have been the Saltmaw rising. If adopted, Aldrec\u2019s people were spent not against raiders but as a distraction offered to a leviathan, which sharpens his grievance from cruelty to sacrilege. If not adopted, the Saltmaw is simply the strait\u2019s terrible fact and the tithe\u2019s reason."));
children.push(H3("The Fjell Whites \u2014 the Ardven Ranges"));
children.push(P("A brood of young white dragons (SRD) in the high north \u2014 Karvel\u2019s standing predator-control problem, culled by the Fjellgard rangers like wolves-of-state. The unconfirmed adult matriarch is the north\u2019s quiet dread and a ready-made mid-campaign escalation: if she exists and wakes, Ardven\u2019s working restoration meets its first problem that cannot be administered, audited, or crowned away \u2014 timed, if the DM wishes, terribly close to the coronation."));
children.push(H3("Rumors of Wings (Player-Facing Texture, d6)"));
children.push(table(["d6","Rumor (and the truth)"],[10,90],[
  ["1","\u2018Gold seen over the Velmareth delta at dusk.\u2019 (A wyvern flock in low sun. Merchants embellish.)"],
  ["2","\u2018The Saltmaw took a Compact grain-ship whole.\u2019 (True. The ship had skipped the tithe two years running.)"],
  ["3","\u2018A white wing over Karvholm itself.\u2019 (A young Fjell White, lost in cloud, gone by morning \u2014 but Karvel doubled the rangers.)"],
  ["4","\u2018The Silvasse eats compasses. And legions.\u2019 (Both, in a sense, true.)"],
  ["5","\u2018There is a dragon under Aenodira.\u2019 (False \u2014 and the DM should let players chew this one, because what is under Aenodira is worse, and the rumor is the city\u2019s way of almost knowing it.)"],
  ["6","\u2018The Matron\u2019s own wolf flies on nights of the dark moon.\u2019 (Faith, not zoology. Probably.)"]
]));


