SB({ name: "Saint-Regent Olvesa the Reconciled", meta: "Medium humanoid (human), lawful neutral \u2014 Cleric (Life; true visions)",
  ac: "13 (sanctified vestments \u2014 she has not worn armor in nearly sixty years)", hp: "117 (18d8 + 36)", speed: "25 ft.",
  str: 10, dex: 10, con: 14, int: 15, wis: 20, cha: 17,
  saves: "Wis +9, Cha +7", skills: "History +6, Insight +9, Medicine +9, Religion +6",
  senses: "passive Perception 15", langs: "Orlathine, Common, Old Imperial, Drevic (she has not spoken it aloud in sixty years)", cr: "10 (5,900 XP)",
  traits: [
    { n: "The Reconciled", t: "A creature that attempts to attack Olvesa directly must first succeed on a DC 17 Wisdom saving throw (as sanctuary, permanent, self-only) \u2014 not divine protection, exactly: the full weight of looking at her and knowing everything she has done and everything she became afterward. On a success, the creature is immune for 24 hours. She has been struck four times in nearly sixty years. She remembers each one kindly." },
    { n: "True Visions", t: "Olvesa casts as a 13th-level cleric (spell save DC 17): spirit guardians (appearing as gray wolves), flame strike (she weeps when she casts it \u2014 the birds), heal, greater restoration, divination \u2014 and her divinations are TRUE, which is the entire geopolitical problem." },
    { n: "The Four Movements (DM only)", t: "If the campaign ever requires Olvesa at war rather than at prayer, do not build it as a fight. Build it as a horror scene with a stat block attached. She has not forgotten how. That is what the Reconciliation is FOR." }
  ],
  actions: [
    { n: "Shepherd\u2019s Crook", t: "Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 3 (1d6) bludgeoning damage. It is a walking stick. She is eighty." }
  ] }).forEach(x => children.push(x));

